ON CONFLICT (name) DO UPDATE SET
  grade=EXCLUDED.grade, lat=EXCLUDED.lat, lng=EXCLUDED.lng,
  access_level=EXCLUDED.access_level, transit_minutes=EXCLUDED.transit_minutes,
  station_to_place=EXCLUDED.station_to_place, is_active=EXCLUDED.is_active;

-- 1) 업소: external_id 로 연결
UPDATE dart_candidates d SET place_id = p.id
  FROM places p
 WHERE p.external_id = d.place_external_id AND d.place_external_id IS NOT NULL;

-- 2) 온천마을: places 의 VILLAGE 행은 external_id 가 없어 이름으로 연결
UPDATE dart_candidates d SET place_id = p.id
  FROM places p
 WHERE p.name = d.place_name AND d.place_name IS NOT NULL AND d.place_id IS NULL;

COMMIT;

